namespace sv_cad867be045a4aa49cbd5213b7ca3db1.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state
/// and notifies all subscribers when it changes.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme != value)
            {
                _theme = value;
                NotifyChanged();
            }
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor != value)
            {
                _accentColor = value;
                NotifyChanged();
            }
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island in the static layout — reacts to ThemeService changes *@
@rendermode InteractiveServer
@inject sv_cad867be045a4aa49cbd5213b7ca3db1.Services.ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        sv_cad867be045a4aa49cbd5213b7ca3db1.Services.ThemeMode.Light => "☀️",
        sv_cad867be045a4aa49cbd5213b7ca3db1.Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject sv_cad867be045a4aa49cbd5213b7ca3db1.Services.ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width: 200px;"
            value="@ThemeService.Theme"
            @onchange="OnThemeChanged">
        @foreach (var mode in Enum.GetValues<sv_cad867be045a4aa49cbd5213b7ca3db1.Services.ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentColorChanged" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @ThemeService.AccentColor !important;">
    <strong>Preview:</strong> Theme is <em>@ThemeService.Theme</em>,
    accent is <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>.
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<sv_cad867be045a4aa49cbd5213b7ca3db1.Services.ThemeMode>(
                e.Value?.ToString(), out var mode))
        {
            ThemeService.Theme = mode;
        }
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

